{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Diffs",
    "description": "Diffs Controller",
    "definitions": {
        "actions": {
            "single_commit": {
                "type": "object",
                "required": [
                    "data"
                ],
                "properties": {
                    "data": {
                        "type": "object",
                        "required": [
                            "repository"
                        ],
                        "properties": {
                            "repository": {
                                "oneOf": [
                                    {
                                        "type": "object",
                                        "required": [
                                            "commit"
                                        ],
                                        "properties": {
                                            "commit": {
                                                "oneOf": [
                                                    {
                                                        "type": "object",
                                                        "required": [
                                                            "diff"
                                                        ],
                                                        "properties": {
                                                            "diff": {
                                                                "type": "array",
                                                                "items": {
                                                                    "$ref": "#/definitions/diff"
                                                                }
                                                            }
                                                        }
                                                    },
                                                    {
                                                        "type": "null"
                                                    }
                                                ]
                                            }
                                        }
                                    },
                                    {
                                        "type": "null"
                                    }
                                ]
                            }
                        }
                    }
                }
            },
            "commit_range": {
                "type": "object",
                "required": [
                    "data"
                ],
                "properties": {
                    "data": {
                        "type": "object",
                        "required": [
                            "repository"
                        ],
                        "properties": {
                            "repository": {
                                "oneOf": [
                                    {
                                        "type": "object",
                                        "required": [
                                            "diff"
                                        ],
                                        "properties": {
                                            "diff": {
                                                "type": "array",
                                                "items": {
                                                    "$ref": "#/definitions/diff"
                                                }
                                            }
                                        }
                                    },
                                    {
                                        "type": "null"
                                    }
                                ]
                            }
                        }
                    },
                    "errors": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "required": [
                                "locations",
                                "message",
                                "path"
                            ],
                            "properties": {
                                "locations": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "required": [
                                            "column",
                                            "line"
                                        ],
                                        "properties": {
                                            "column": {
                                                "type": "integer",
                                                "example": 13,
                                                "description": "The column of the error in the input data"
                                            },
                                            "line": {
                                                "type": "integer",
                                                "example": 3,
                                                "description": "The line of the error in the input data"
                                            }
                                        }
                                    }
                                },
                                "message": {
                                    "type": "string",
                                    "example": "\"from\" revspec 'mastor' not found",
                                    "description": "The error message"
                                },
                                "path": {
                                    "type": "array",
                                    "items": {
                                        "type": "string",
                                        "example": "repository",
                                        "description": "A path segment pointing to the error in the input data"
                                    }
                                }
                            }
                        }
                    }
                }
            }
        },
        "diff": {
            "type": "object",
            "required": [
                "deletedFile",
                "diff",
                "lineCount",
                "newFile",
                "newMode",
                "newPath",
                "oldMode",
                "oldPath",
                "renamedFile"
            ],
            "properites": {
                "deletedFile": {
                    "type": "boolean",
                    "example": false,
                    "description": "True if the file was deleted"
                },
                "diff": {
                    "type": "string",
                    "example": "--- /dev/null\n+++ b/texts/ontohub_changed.txt\n@@ -0,0 +1 @@\n+The main Ontohub service that serves the data for the frontend and other clients via the GraphQL API.\n",
                    "description": "The actual diff"
                },
                "lineCount": {
                    "type": "integer",
                    "example": 4,
                    "description": "The number of changed lines"
                },
                "newFile": {
                    "type": "boolean",
                    "example": true,
                    "description": "True if the file was added"
                },
                "newMode": {
                    "type": "string",
                    "example": "100644",
                    "description": "The file mode in the new state"
                },
                "newPath": {
                    "type": "string",
                    "example": "texts/ontohub_changed.txt",
