                                    "username": {
                                        "type": "string",
                                        "description": "The username to be used for Basic Authentication is stored in this field."
                                    },
                                    "password": {
                                        "type": "string",
                                        "description": "The password to be used for digest Authentication is stored in this field."
                                    }
                                },
                                "required": [
