                        ]
                    },
                    "pattern": "\\d{4}-((0[1-9])|(1[0-2]))-(((0[1-9])|[1-2][0-9])|(3[0-1]))$",
                    "title": "Expected date",
                    "type": "string",
                    "validationMessage": "Should be in the following format: 2022-12-31 (YYYY-MM-DD)."
                },
                "received_date": {
                    "_format": "date",
                    "form": {
                        "type": "datepicker",
                        "validation": {
                            "messages": {
                                "pattern": "Should be in the ISO 8601, YYYY-MM-DD."
                            }
                        },
                        "wrappers": [
                            "form-field"
                        ]
                    },
                    "pattern": "\\d{4}-((0[1-9])|(1[0-2]))-(((0[1-9])|[1-2][0-9])|(3[0-1]))$",
                    "title": "Date of reception",
                    "type": "string",
                    "validationMessage": "Should be in the following format: 2022-12-31 (YYYY-MM-DD)."
                },
                "regular": {
                    "default": true,
                    "form": {
                        "hideExpression": "true"
                    },
                    "title": "Regularity",
                    "type": "boolean"
                },
                "status": {
                    "default": "received",
                    "enum": [
                        "received",
                        "claimed",
                        "deleted"
                    ],
                    "title": "Issue status",
                    "type": "string"
                }
            },
            "propertiesOrder": [
                "display_text",
                "received_date",
                "expected_date",
                "regular",
                "status"
            ],
            "required": [
                "display_text",
                "received_date",
                "expected_date",
                "regular",
                "status"
            ],
            "title": "Issue",
            "type": "object"
        },
        "item_type": {
            "form": {
                "hideExpression": "field.parent.model.type === 'issue'"
            },
            "properties": {
                "$ref": {
                    "form": {
                        "remoteOptions": {
                            "type": "item_types"
                        }
                    },
                    "pattern": "^https://ils.rero.ch/api/item_types/.+?$",
                    "title": "Item Type URI",
                    "type": "string"
                }
            },
            "required": [
                "$ref"
            ],
            "title": "Circulation category of the item",
            "type": "object"
        },
        "location": {
            "form": {
                "hideExpression": "field.parent.model.type === 'issue'"
            },
            "properties": {
                "$ref": {
                    "form": {
                        "fieldMap": "location"
                    },
                    "pattern": "^https://ils.rero.ch/api/locations/.+?$",
                    "title": "Location URI",
                    "type": "string"
                }
            },
            "required": [
                "$ref"
            ],
            "title": "Location",
            "type": "object"
        },
        "notes": {
            "form": {
                "validation": {
                    "messages": {
                        "uniqueValueKeysInObjectMessage": "Only one note per type is allowed"
                    },
                    "validators": {
                        "uniqueValueKeysInObject": {
                            "keys": [
                                "type"
                            ]
                        }
                    }
                }
            },
            "items": {
                "properties": {
                    "content": {
                        "form": {
                            "templateOptions": {
                                "rows": 3
                            },
                            "type": "textarea"
                        },
                        "maxLength": 2000,
                        "minLength": 3,
                        "title": "Content",
                        "type": "string"
                    },
                    "type": {
                        "enum": [
                            "public_note",
                            "staff_note",
                            "checkin_note",
                            "checkout_note"
                        ],
                        "form": {
                            "options": [
                                {
                                    "label": "public note",
                                    "value": "public_note"
                                },
                                {
                                    "label": "staff note",
                                    "value": "staff_note"
                                },
                                {
                                    "label": "checkin note",
                                    "value": "checkin_note"
                                },
                                {
                                    "label": "checkout note",
                                    "value": "checkout_note"
                                }
                            ]
                        },
                        "title": "Type",
                        "type": "string"
                    }
                },
                "propertiesOrder": [
                    "type",
                    "content"
                ],
                "required": [
                    "type",
                    "content"
                ],
                "title": "Note",
                "type": "object"
            },
            "title": "Notes",
            "type": "array"
        },
        "organisation": {
            "properties": {
                "$ref": {
                    "pattern": "^https://ils.rero.ch/api/organisations/.*?$",
                    "title": "Organisation URI",
                    "type": "string"
                }
            },
            "title": "Organisation",
            "type": "object"
        },
        "pid": {
            "minLength": 1,
            "title": "Item ID",
            "type": "string"
        },
        "status": {
            "default": "on_shelf",
            "enum": [
                "on_shelf",
                "on_loan",
                "missing",
                "in_transit",
                "at_desk",
                "excluded"
            ],
            "form": {
                "hideExpression": "true",
                "options": [
                    {
                        "label": "on_shelf",
                        "value": "on_shelf"
                    },
                    {
                        "label": "on_loan",
                        "value": "on_loan"
                    },
                    {
                        "label": "missing",
                        "value": "missing"
                    },
                    {
                        "label": "in_transit",
                        "value": "in_transit"
                    },
                    {
                        "label": "at_desk",
                        "value": "at_desk"
                    },
                    {
                        "label": "excluded",
                        "value": "excluded"
                    }
                ]
            },
            "readOnly": true,
            "title": "circulation status",
            "type": "string"
        },
        "type": {
            "default": "standard",
            "enum": [
                "standard",
                "issue"
            ],
            "form": {
                "hideExpression": "true"
            },
            "title": "Item type",
            "type": "string"
        }
    },
    "propertiesOrder": [
        "barcode",
        "call_number",
        "item_type",
        "location",
        "status",
        "type",
        "status",
        "issue",
        "notes"
    ],
    "required": [
        "$schema",
        "pid",
        "location",
        "barcode",
        "item_type",
        "type",
        "document",
        "status"
    ],
    "title": "Item",
    "type": "object"
}

{
    "id": "http://cachemanager.michaco.net/schemas/cachemanager.json",
    "title": "JSON schema for CacheManager configuration files",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "definitions": {
        "configurationKey": {
            "type": "string",
            "description": "The key to identify this entity by other parts of the configuration. The key must be unique for all entities of the collection.",
            "minLength": 1
        },
        "expirationMode": {
            "type": "string",
            "enum": [
                "None",
                "Absolute",
                "Sliding"
            ],
            "description": "The expiration mode for the current configuration element"
        },
        "expirationTimeout": {
            "type": "string",
            "description": "The expiration timeout in milliseconds (only required if expirationMode is not None)",
            "minLength": 1,
            "format": "regex",
            "pattern": "^((?:-?0*\\d+\\.)?(?:0*)(?:2[0-3]|1[0-9]|[0-9]))(?::0*([0-5]?[0-9]))?(?::0*((?:[0-5]?[0-9])(?:\\.\\d{0,7})?))?$"
        },
        "host": {
            "type": "string",
            "oneOf": [
                {
                    "format": "hostname"
                },
                {
                    "format": "ipv4"
                },
                {
                    "format": "ipv6"
                }
            ],
            "description": "The host name or IP address."
        },
        "channelName": {
            "type": "string",
            "minLength": 1,
            "description": "If specified, this name will be used for communication channels, if applicable"
        },
        "knownBackplane": {
            "type": "object",
            "required": [
                "key",
                "knownType"
            ],
            "properties": {
                "key": {
                    "$ref": "#/definitions/configurationKey"
                },
                "knownType": {
                    "type": "string",
                    "enum": [
                        "Redis"
                    ],
                    "description": "Choose one of the known backplane types instead of typing the full type name. The corresponding package for the backplane implementation must be installed."
                },
                "channelName": {
                    "$ref": "#/definitions/channelName"
                }
            },
            "additionalProperties": false
        },
        "unknownBackplane": {
            "type": "object",
            "required": [
                "type",
                "key"
            ],
            "properties": {
                "type": {
                    "type": "string",
                    "description": "The clr type of a backplane implementation."
                },
                "key": {
                    "$ref": "#/definitions/configurationKey"
                },
                "channelName": {
                    "$ref": "#/definitions/channelName"
                }
            },
            "additionalProperties": false
        },
        "knownLoggerFactory": {
            "type": "object",
            "required": [
                "knownType"
            ],
            "properties": {
                "knownType": {
                    "type": "string",
                    "enum": [
                        "Microsoft"
                    ],
                    "description": "Choose one of the known logger factories instead of typing the full type name. The corresponding package for the logger factory must be installed."
                }
            },
            "additionalProperties": false
        },
        "unknownLoggerFactory": {
            "type": "object",
            "required": [
                "type"
            ],
            "properties": {
                "type": {
                    "type": "string",
                    "description": "The clr type of a logger factory which should be used by CacheManager to log events."
                }
            },
            "additionalProperties": false
        },
        "knownSerializer": {
            "type": "object",
            "required": [
                "knownType"
            ],
            "properties": {
                "knownType": {
                    "type": "string",
                    "enum": [
                        "Binary",
                        "Json",
                        "Protobuf",
                        "GzJson",
                        "BondCompactBinary",
                        "BondFastBinary",
                        "BondSimpleJson"
                    ],
                    "description": "Define a known serializer type instead of setting 'serializerType'. The respective library has to be installed. The default 'binary' might not be available on all platforms."
                }
            },
            "additionalProperties": false
        },
        "unknownSerializer": {
            "type": "object",
            "required": [
                "type"
            ],
            "properties": {
                "type": {
                    "type": "string",
                    "description": "The clr type of the serializer to be used by distributed cache handles."
                }
            },
            "additionalProperties": false
        },
        "knownHandle": {
            "type": "object",
            "required": [
                "knownType"
            ],
            "properties": {
                "knownType": {
                    "type": "string",
                    "enum": [
                        "SystemRuntime",
                        "Dictionary",
                        "SystemWeb",
                        "MsMemory"
                    ],
                    "description": "Shortcut to the known cache handle types. This requires the corresponding packages are installed."
                }
            }
        },
        "knownHandleWithConfigurationKey": {
            "type": "object",
            "required": [
                "knownType",
                "key"
            ],
            "properties": {
                "knownType": {
                    "type": "string",
                    "enum": [
                        "Redis",
                        "Couchbase",
                        "Memcached"
                    ],
                    "description": "Shortcut to the known cache handle types. This requires the corresponding packages are installed."
                },
                "key": {
                    "$ref": "#/definitions/configurationKey"
                }
            }
        },
        "unknownHandle": {
            "type": "object",
            "required": [
                "type"
            ],
            "properties": {
                "type": {
                    "type": "string",
                    "description": "The clr type of the cache handle. Must be an open generic type definition.",
                    "minLength": 1
                },
                "key": {
                    "$ref": "#/definitions/configurationKey"
                }
            }
        },
        "handle": {
            "type": "object",
            "oneOf": [
                {
                    "$ref": "#/definitions/knownHandle"
                },
                {
                    "$ref": "#/definitions/knownHandleWithConfigurationKey"
                },
                {
                    "$ref": "#/definitions/unknownHandle"
                }
            ],
            "_uniqueItems": true,
            "properties": {
                "name": {
                    "type": "string",
                    "description": "The name of the cache handle."
                },
                "expirationMode": {
                    "$ref": "#/definitions/expirationMode"
                },
                "expirationTimeout": {
                    "$ref": "#/definitions/expirationTimeout"
                },
                "isBackplaneSource": {
                    "type": "boolean",
                    "description": "Determines if the cache handle is the backplane's source. (optional; if no backplane is defined, this can stay empty. If a backplane is defined, at least one handle must be flagged.)"
                },
                "enablePerformanceCounters": {
                    "type": "boolean",
                    "description": "Defines if windows performance counters should be enabled or not."
                },
                "enableStatistics": {
                    "type": "boolean",
                    "description": "Defines if statistics should be captured."
                }
            }
        },
        "manager": {
            "description": "The configuration for one CacheManager instance.",
            "type": "object",
            "required": [
                "handles"
            ],
            "default": {
                "handles": []
            },
            "additionalProperties": false,
            "properties": {
                "name": {
                    "type": "string",
                    "description": "The name of the cache manager instance."
                },
                "updateMode": {
                    "type": "string",
                    "enum": [
                        "None",
                        "Full",
                        "Up"
                    ],
                    "description": "The update mode (default is Up).",
                    "default": "Up"
                },
                "maxRetries": {
                    "type": "integer",
                    "minimum": 0,
                    "description": "The number of retries in case the cache action fails before the cache manager throws the exception (default is 50)."
                },
                "retryTimeout": {
                    "type": "integer",
                    "minimum": 0,
                    "description": "The time between retries (default is 100)."
                },
                "backplane": {
                    "type": "object",
                    "description": "The backplane configuration.",
                    "oneOf": [
                        {
                            "$ref": "#/definitions/knownBackplane"
                        },
                        {
                            "$ref": "#/definitions/unknownBackplane"
                        }
                    ]
                },
                "loggerFactory": {
                    "type": "object",
                    "description": "The logger factory configuration.",
                    "oneOf": [
                        {
                            "$ref": "#/definitions/knownLoggerFactory"
                        },
                        {
                            "$ref": "#/definitions/unknownLoggerFactory"
                        }
                    ]
                },
                "serializer": {
                    "type": "object",
                    "description": "The logger factory configuration.",
                    "oneOf": [
                        {
                            "$ref": "#/definitions/knownSerializer"
                        },
                        {
                            "$ref": "#/definitions/unknownSerializer"
                        }
                    ]
                },
                "handles": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/handle"
                    },
                    "description": "The collection of cache handles the CacheManager instance should use.",
                    "minItems": 1
                }
            }
        },
        "redisConnectionString": {
            "description": "A connection string based redis configuration.",
            "additionalProperties": false,
            "type": "object",
            "required": [
                "key",
                "connectionString"
            ],
            "properties": {
                "key": {
                    "$ref": "#/definitions/configurationKey"
                },
                "connectionString": {
                    "type": "string",
                    "minLength": 1,
                    "description": "The StackExchange.Redis connection string, see https://github.com/StackExchange/StackExchange.Redis/blob/master/Docs/Configuration.md."
                },
                "strictCompatibilityModeVersion": {
                    "type": "string",
                    "description": "Set an explicit version to restrict features available to CacheManager. Set this to 2.4 for example to disallow LUA scripting.",
                    "minLength": 1
                },
                "twemproxyEnabled": {
                    "type": "boolean",
                    "description": "Set this to true only if you are using Twemproxy."
                },
                "database": {
                    "type": "integer",
                    "minimum": 0,
                    "description": "The database to be used on the redis instance."
                }
            }
        },
        "redisConfiguration": {
            "description": "A redis configuration.",
            "additionalProperties": false,
            "type": "object",
            "required": [
                "key",
                "endpoints"
            ],
            "properties": {
                "key": {
                    "$ref": "#/definitions/configurationKey"
                },
                "password": {
                    "type": "string",
                    "description": "The server password.",
                    "minLength": 1
                },
                "strictCompatibilityModeVersion": {
                    "type": "string",
                    "description": "Set an explicit version to restrict features available to CacheManager. Set this to 2.4 for example to disallow LUA scripting.",
                    "minLength": 1
                },
                "twemproxyEnabled": {
                    "type": "boolean",
                    "description": "Set this to true only if you are using Twemproxy."
                },
                "keyspaceNotificationsEnabled": {
                    "type": "boolean",
                    "description": "If set to true, CacheManager will listen to evicted and expired keyevent notifications. In redis, notify-keyspace-events must be set to at least Exe, otherwise the feature will not work."
                },
                "allowAdmin": {
                    "type": "boolean",
                    "description": "If set to true, enables certain commands which might be time intensive, e.g. FLUSHDB."
                },
                "isSsl": {
                    "type": "boolean",
                    "description": "Defines if an ssl connection should be used."
                },
                "sslHost": {
                    "$ref": "#/definitions/host",
                    "description": "The ssl host to be used in conjunction with the ssl flag."
                },
                "database": {
                    "type": "integer",
                    "minimum": 0,
                    "description": "The database to be used on the redis instance."
                },
                "connectionTimeout": {
                    "type": "integer",
                    "minimum": 0,
                    "description": "The time in milliseconds before the connection attempt gets timed out."
                },
                "endpoints": {
                    "type": "array",
                    "minItems": 1,
                    "description": "The collection of redis hosts.",
                    "items": {
                        "required": [
                            "host",
                            "port"
                        ],
                        "type": "object",
                        "properties": {
                            "host": {
                                "$ref": "#/definitions/host"
                            },
                            "port": {
                                "type": "integer",
                                "minimum": 0,
                                "maximum": 65535,
                                "description": "The port number of the redis host."
                            }
                        }
                    }
                }
            }
        }
    },
    "properties": {
        "cacheManagers": {
            "description": "The collection of CacheManager configurations.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/manager"
            },
            "minItems": 1,
            "_uniqueItems": true,
            "default": []
        },
        "redis": {
            "type": "array",
            "description": "The redis options. Use the 'key' of each item to reference them by other parts of the configuration.",
            "items": {
                "anyOf": [
                    {
                        "$ref": "#/definitions/redisConfiguration"
                    },
                    {
                        "$ref": "#/definitions/redisConnectionString"
                    }
                ]
            },
            "_uniqueItems": true,
            "minItems": 1
        }
    },
    "required": [
        "cacheManagers"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "definitions": {
        "responseType": {
            "description": "Response type, as defined by the Open311/GeoReport2 standard.",
            "type": "string",
            "enum": [
                "realtime",
                "batch",
                "blackbox"
            ]
        },
        "service": {
            "description": "All requests are for a Service.",
            "type": "object",
            "properties": {
                "id": {
                    "description": "The id must be unique",
                    "type": "number",
                    "minimum": 1
                },
                "name": {
                    "description": "Title of the Service.",
                    "type": "string"
                },
                "responseType": {
                    "description": "Response type, as defined by the Open311/GeoReport2 standard.  This overrides anything set at the Provider level.",
                    "$ref": "#/definitions/responseType"
                },
                "group": {
                    "description": "The group this Service request type belongs to.",
                    "type": "string"
                }
            },
            "required": [
                "id",
                "name",
                "group"
            ]
        },
        "emailCfg": {
            "description": "Email configuration: to, from, subject, and template.",
            "type": "object",
            "properties": {
                "to": {
                    "description": "Email will be sent to this address(es).",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "from": {
                    "description": "Email marked as being sent by this address and sender.",
                    "type": "array",
                    "items": {
                        "description": "The first string is the sender address, the second string is the sender name.",
                        "type": "string"
                    }
                },
                "subject": {
                    "description": "The subject line of the email.",
                    "type": "string"
                },
                "template": {
                    "description": "The Go template to use to format the email.  This is the path and filename of the template file.",
                    "type": "string"
                }
            }
        },
        "provider": {
            "description": "A specific Service Provider interface.",
            "type": "object",
            "properties": {
                "id": {
                    "description": "A number uniquely identifying the Service Provider.  This is only used within the Gateway system, and must be unique and unchanging. New values should be placed numerically ABOVE existing values.  Changing the values will confuse any issue ID's that may be stored in a user device.",
                    "type": "number",
                    "minimum": 1
                },
                "name": {
                    "description": "Identifies the Service Provider instance.  This should be unique, as it will be used in error and log messages.",
                    "type": "string"
                },
                "url": {
                    "description": "The URL of the Service Provider interface.",
                    "type": "string"
                },
                "apiVersion": {
                    "description": "The API version of the Service Provider interface.  Not currently used.",
                    "type": "string"
                },
                "key": {
                    "description": "The API key to access the Service Provider interface.",
                    "type": "string"
                },
                "responseType": {
                    "description": "Response type, as defined by the Open311/GeoReport2 standard.  This sets the default value for the Provider, which can be overridden at the Service level.",
                    "$ref": "#/definitions/responseType"
                },
                "email": {
                    "description": "The email configuration for this Provider.  Only applies to the Email adapter.",
                    "$ref": "#/definitions/emailCfg"
                },
                "services": {
                    "description": "The Services of the Provider.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/service"
                    }
                }
            },
            "required": [
                "id",
                "name",
                "responseType",
                "services"
            ]
        },
        "serviceArea": {
            "description": "A Service Area, having one or more Service Providers.",
            "type": "object",
            "properties": {
                "name": {
                    "description": "Name of the Area.",
                    "type": "string"
                },
                "providers": {
                    "description": "The list of all Providers for this Area.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/provider"
                    }
                }
            },
            "required": [
                "name",
                "providers"
            ]
        }
    },
    "properties": {
        "adapter": {
            "description": "Basic configuration info for the Adapter",
            "type": "object",
            "properties": {
                "name": {
                    "description": "Identifies the Adapter to the Engine. This must match the Engine configuration file.",
                    "type": "string"
                },
                "type": {
                    "description": "The type of Adapter - e.g. 'CitySourced', 'Email', etc.",
                    "type": "string"
                },
                "address": {
                    "description": "The IP address and port number over which the Adapter will communicate with the Engine.",
                    "type": "string"
                }
            },
            "required": [
                "name",
                "type",
                "address"
            ]
        },
        "monitor": {
            "description": "Configuration data for the System Monitor.",
            "type": "object",
            "properties": {
                "address": {
                    "description": "IP and port of the system monitor.",
                    "type:": "string"
                }
            },
            "required": [
                "address"
            ]
        },
        "serviceGroups": {
            "description": "The list of all top level categories for all Services.  These will be referenced in the serviceAreas.",
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "serviceAreas": {
            "description": "The list of all geographic areas the Adapter services, including the list of all services for each area.",
            "additionalProperties": {
                "$ref": "#/definitions/serviceArea"
            }
        }
    }
}

{
  "type": "object",
  "description": "DForms Form Schema",
  "required": [
    "sections"
