                        ]
                    },
                    "minItems": 1,
                    "readOnly": true,
                    "type": [
                        "array",
                        "null"
                    ],
                    "_uniqueItems": true
                },
                "created_at": {
                    "description": "when kindle was created",
                    "example": "2015-01-01T00:00:00.000Z",
                    "format": "date-time",
                    "type": [
                        "string"
                    ]
                },
