                    "info": "Explains why the SP answered no on the subject of the SURFmarket DPA."
                },
                "coin:privacy:privacy_policy": {
                    "type": "boolean",
                    "info": "Does the SP publish an applicable privacy policy on a web page?"
                },
                "coin:privacy:privacy_policy_url": {
                    "type": "string",
                    "format": "url",
                    "info": "The URL to the applicable privacy policy. "
                },
                "coin:privacy:other_info": {
                    "type": "string",
                    "info": "Other data privacy and security information that helps the institution decide whether it is OK to connect the service."
                },
                "coin:signature_method": {
                    "type": "string",
                    "format": "url",
                    "enum": [
                        "http://www.w3.org/2000/09/xmldsig#rsa-sha1",
                        "http://www.w3.org/2001/04/xmldsig-more#rsa-sha256"
                    ],
                    "default": "http://www.w3.org/2001/04/xmldsig-more#rsa-sha256",
                    "info": "Select the Secure Hash Algorithm (SHA) as used by the service provider."
                },
                "coin:privacy:gdpr_is_in_wiki": {
                    "type": "boolean",
                    "info": "Set if the 'General Data Protection Regulation' (GDPR) is available on the SURF wiki. In Dutch known as 'Algemene Verordening Gegevensbescherming' (AVG). "
                },
                "coin:ss:license_status": {
                    "type": "string",
                    "enum": [
                        "license_required_by_service_provider",
                        "license_not_required",
                        "license_available_through_surfmarket"
                    ],
                    "default": "license_required_by_service_provider",
                    "info": "Set the applicable license for this service as provisioned by the SP Dashboard."
                },
                "coin:stepup:requireloa": {
                    "type": "string",
                    "format": "url",
                    "enum": [
                        "http://test.surfconext.nl/assurance/loa2",
                        "http://test.surfconext.nl/assurance/loa3"
                    ],
                    "info": "Set to require Stepup Authentication for this SP with the specified minimum Level of Assurance."
                },
                "coin:stepup:allow_no_token": {
                    "type": "boolean",
                    "info": "When Stepup Authentication is required for this SP, allow users without a registered token to log in regardless."
                },
                "coin:contractual_base": {
                    "type": "string",
                    "enum": [
                        "AO",
                        "IX",
                        "R&S+CoCo",
                        "Entree",
                        "Clarin"
                    ],
                    "default": "AO",
                    "info": "Set the contractual base that underlies a production SP / RP entity."
                }
            },
            "patternProperties": {
                "^name:(en|nl)$": {
                    "type": "string",
                    "info": "Set the name of the service. Format: 'Service Name | Supplier'"
                },
                "^displayName:(en|nl)$": {
                    "type": "string",
                    "info": "Name as displayed in applications."
                },
                "^coin:ss:wiki_url:(en|nl)$": {
                    "type": "string",
                    "format": "url",
                    "info": "Add the URL to the SURF wiki for additional information of this service."
                },
                "^description:(en|nl)$": {
                    "type": "string",
                    "info": "The description of the service."
                },
                "^coin:ss:type_of_service:(en|nl)$": {
                    "type": "string",
                    "info": "The type of service used in the facet search in dashboard."
                },
                "^AssertionConsumerService:([0-9]{1}):Binding$": {
                    "$ref": "#/definitions/AssertionConsumerServiceBinding",
                    "multiplicity": 10,
                    "info": "An Assertion Consumer Service (or ACS) the location at a ServiceProvider that accepts <samlp:Response> messages. The type of binding for this location can be selected from the pull-down."
                },
                "^AssertionConsumerService:([0-9]{1}):Location$": {
                    "type": "string",
                    "format": "url",
                    "multiplicity": 10,
                    "info": "An Assertion Consumer Service (or ACS) is the location at a ServiceProvider that accepts <samlp:Response> messages. A typical ACS location for an SP might look like this: https://data.example-service.nl/saml/saml2_acs/"
                },
                "^AssertionConsumerService:([0-9]{1}):index$": {
                    "type": "number",
                    "multiplicity": 10,
                    "info": "An Assertion Consumer Service (or ACS) is the location at a ServiceProvider that accepts <samlp:Response> messages. With the index you can include additional <md:AssertionConsumerService> elements in the SAML 2.0 SP metadata with the same binding, each with its own unique index."
                },
                "^NameIDFormats:([0-2]{1})$": {
                    "$ref": "#/definitions/NameIDFormat",
                    "multiplicity": 3,
                    "info": "The format in which the service expects the response. This can be transient, transparant or unspecified."
                },
                "^contacts:([0-3]{1}):surName$": {
                    "type": "string",
                    "multiplicity": 4,
                    "sibblingIndependent": true,
                    "info": "The surname of the contact. e.g. for 'John Doe', 'Doe' is the surname."
                },
                "^contacts:([0-3]{1}):givenName$": {
                    "type": "string",
                    "multiplicity": 4,
                    "sibblingIndependent": true,
                    "info": "The given name of the contact. e.g. for 'John Doe', 'John' is the given name."
                },
                "^contacts:([0-3]{1}):emailAddress$": {
                    "type": "string",
                    "format": "local-email",
                    "multiplicity": 4,
                    "sibblingIndependent": true,
                    "info": "The e-mail address; syntax in accordance with RFC 5322. e.g. m.l.vermeegen@university.example.org."
                },
                "^contacts:([0-3]{1}):telephoneNumber$": {
                    "type": "string",
                    "multiplicity": 4,
                    "sibblingIndependent": true,
                    "info": "The telephone number of the contact."
                },
                "^contacts:([0-3]{1}):isSirtfiSecurityContact$": {
                    "type": "boolean",
                    "multiplicity": 4,
                    "sibblingIndependent": true,
                    "info": "Set the security contact for this service."
                },
                "^contacts:([0-3]{1}):contactType$": {
                    "type": "string",
                    "enum": [
                        "technical",
                        "support",
                        "administrative",
                        "billing",
                        "other"
                    ],
                    "multiplicity": 4,
                    "sibblingIndependent": true,
                    "info": "From the pull down, select the type of contact."
                },
                "^OrganizationName:(en|nl)$": {
                    "type": "string",
                    "info": "The formal name of the organization. e.g. Service by University of Harderwijk."
                },
                "^OrganizationDisplayName:(en|nl)$": {
                    "type": "string",
                    "info": "The friendly name of the organization. e.g. University of Harderwijk."
                },
                "^OrganizationURL:(en|nl)$": {
                    "type": "string",
                    "format": "url",
                    "info": "The URL to the website of the service e.g. http://www.example-service.nl/en/."
                },
                "^url:(en|nl)$": {
                    "type": "string",
                    "format": "url",
                    "info": "The URL to the support site of the service."
                },
                "^mdui:PrivacyStatementURL:(en|nl)$": {
                    "type": "string",
                    "format": "url",
                    "info": "The URL to the Privacy Statement of the service."
                },
                "^mdrpi:RegistrationPolicy:(en|nl)$": {
                    "type": "string",
                    "info": "The URL to the Registration Policy of the service."
                },
                "^coin:entity_categories:([1-4]{1})$": {
                    "type": "string",
                    "enum": [
                        "http://refeds.org/category/research-and-scholarship",
                        "http://refeds.org/category/hide-from-discovery",
                        "http://www.geant.net/uri/dataprotection-code-of-conduct/v1",
                        "http://clarin.eu/category/clarin-member"
                    ],
                    "multiplicity": 4,
                    "startIndex": 1,
                    "info": "Select one of the entity categories applicable to this service. Entity Categories group federation entities that share common criteria."
                }
            },
            "required": [
                "name:en"
            ],
            "additionalProperties": false
        }
    },
    "required": [
        "state",
        "metaDataFields"
    ],
    "additionalProperties": false,
    "indexes": [
        {
            "name": "field_entityid",
            "type": "field",
            "fields": [
                "entityid"
            ],
            "unique": false
        }
    ]
}

{
    "title": "fabric info",
    "$schema": "http://json-schema.org/draft-06/schema#",
    "type": "object",
    "additionalProperties": false,
    "required": [
        "fabric_fq_name",
        "management_subnets",
        "loopback_subnets",
        "fabric_subnets",
        "fabric_asn_pool",
        "device_auth",
        "node_profiles"
    ],
    "properties": {
        "fabric_fq_name": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "fabric_display_name": {
            "type": "string"
        },
        "fabric_cluster_id": {
            "type": "integer"
        },
        "management_subnets": {
            "type": "array",
            "items": {
                "type": "object",
                "description": "List of the management network subnets for the fabric",
                "additionalProperties": false,
                "required": [
                    "cidr",
                    "gateway"
                ],
                "properties": {
                    "cidr": {
                        "type": "string",
                        "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
                    },
                    "gateway": {
                        "type": "string",
                        "format": "ipv4"
                    }
                }
            }
        },
        "loopback_subnets": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "List of the subnet prefixes that fabric device loopback ips can be allocated.",
                "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
            }
        },
        "overlay_loopback_subnets": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "List of the subnet prefixes that fabric device overlay loopback ips can be allocated.",
                "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
            }
        },
        "fabric_subnets": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "List of the subnet prefixes that could be carved out for the p2p networks between fabric devices.",
                "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
            }
        },
        "pnf_servicechain_subnets": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "List of the subnet prefixes that could be carved out for service chaining between fabric devices.",
                "pattern": "^([0-9]{1,3}\\.){3}[0-9]{1,3}(/([0-9]|[1-2][0-9]|3[0-2]))?$"
            }
        },
        "fabric_asn_pool": {
            "type": "array",
            "items": {
                "title": "eBGP ASN Pool for fabric underlay network",
                "type": "object",
                "description": "List of the ASN pools that could be used to configure the eBGP peers for the IP fabric",
                "properties": {
                    "asn_min": {
                        "type": "integer"
                    },
                    "asn_max": {
                        "type": "integer"
                    }
                },
                "required": [
                    "asn_min",
                    "asn_max"
                ]
            }
        },
        "overlay_ibgp_asn": {
            "type": "integer",
            "title": "iBGP ASN for Contrail overlay network",
            "default": 64512
        },
        "device_auth": {
            "title": "Device Auth",
            "type": "object",
            "additionalProperties": false,
            "required": [
                "root_password"
            ],
            "properties": {
                "root_password": {
                    "type": "string"
                }
            }
        },
        "node_profiles": {
            "type": "array",
            "items": {
                "title": "Node profile",
                "type": "object",
                "description": "List of node profiles to be used by the fabric.",
                "additionalProperties": false,
                "properties": {
                    "node_profile_name": {
                        "type": "string"
                    },
                    "serial_nums": {
                        "type": "array",
                        "description": "Optional list of serial numbers of fabric devices that we want to associate with this node profile.",
                        "items": {
                            "type": "string"
                        }
                    }
                },
                "required": [
                    "node_profile_name"
                ]
            }
        },
        "interface_filters": {
            "type": "array",
            "items": {
                "type": "object",
                "maxProperties": 2,
                "additionalProperties": false,
                "properties": {
                    "op": {
                        "enum": [
                            "regex"
                        ]
                    },
                    "expr": {
                        "type": "string"
                    }
                },
                "title": "filter object",
                "description": "filter object having op and expr fields",
                "default": {},
                "examples": [
                    {
                        "op": "regex",
                        "expr": "^ge-"
                    },
                    {
                        "op": "regex",
                        "expr": "^xe"
                    }
                ]
            }
        },
        "import_configured": {
            "type": "boolean",
            "default": false,
            "description": "Not importing configured interfaces by default. Set this option to true if configured interfaces need to be imported as part of onboarding."
        },
        "device_count": {
            "title": "Number of fabric devices",
            "type": "integer",
            "description": "Total number of devices in the fabric that needs to be zero-touch provisioned"
        },
        "supplemental_day_0_cfg": {
            "title": "List of day 0 config that can be used to supplement the ZTP config",
            "type": "array",
            "items": {
                "type": "object",
                "required": [
                    "name",
                    "cfg"
                ],
                "properties": {
                    "name": {
                        "title": "name for the config",
                        "type": "string"
                    },
                    "cfg": {
                        "title": "config blob that contains the supplemental day-0 config",
                        "type": "string"
                    }
                }
            }
        },
        "device_to_ztp": {
            "title": "List of device serial numbers for the devices to be ZTPed",
            "type": "array",
            "items": {
                "type": "object",
                "required": [
                    "serial_number",
                    "hostname"
                ],
                "properties": {
                    "serial_number": {
                        "title": "Device serial number",
                        "type": "string"
                    },
                    "hostname": {
                        "title": "Device hostname can be optionally specified.",
                        "type": "string",
                        "pattern": "^(([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]*[a-zA-Z0-9])\\.)*([A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\\-]*[A-Za-z0-9])$"
                    },
                    "underlay_asn": {
                        "title": "Underlay eBGP autonomous system number",
                        "type": [
                            "integer",
                            "string"
                        ]
                    },
                    "loopback_ip": {
                        "title": "Loopback IP address",
                        "type": "string",
                        "format": "ipv4"
                    },
                    "mgmt_ip": {
                        "title": "Management IP address",
                        "type": "string",
                        "format": "ipv4"
                    },
                    "to_ztp": {
                        "title": "Include or ignore device in ZTP workflow",
                        "type": "boolean"
                    },
                    "supplemental_day_0_cfg": {
                        "title": "Name(s) of the supplemental day-0 config(s) that can be optionally specified for this device",
                        "type": [
                            "string",
                            "array"
                        ],
                        "items": {
                            "type": "string"
                        }
                    }
                }
            }
        },
        "os_version": {
            "type": "string"
        },
        "enterprise_style": {
            "type": "boolean",
            "default": true,
            "description": "True if enterprise style, false if sp-style configuration"
        },
        "disable_vlan_vn_uniqueness_check": {
            "type": "boolean",
            "default": false,
            "description": "True if vlan-vn uniqueness validation checks needs to be disabled, false if enable all complex validations"
        }
    }
}

