{
    "id": "http://schemas.triniti.io/json-schema/triniti/curator/mixin/tetris-widget/1-0-0.json#",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "_id": {
            "type": "string",
            "pattern": "^[\\w\\/\\.:-]+$",
            "pbj": {
                "type": "identifier",
                "rule": "single",
                "overridable": true
            }
        },
        "status": {
            "type": "string",
            "default": "draft",
            "enum": [
                "unknown",
                "published",
                "scheduled",
                "pending",
                "draft",
                "expired",
                "archived",
                "deleted"
            ],
            "pbj": {
                "type": "string-enum",
                "rule": "single"
            }
        },
        "etag": {
            "type": "string",
            "pattern": "^[\\w\\.:-]+$",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "created_at": {
            "type": "string",
            "pattern": "^[1-9]{1}[0-9]{12,15}$",
            "pbj": {
                "type": "microtime",
                "rule": "single"
            }
        },
        "creator_ref": {
            "type": "object",
            "properties": {
                "curie": {
                    "type": "string",
                    "pattern": "^([a-z0-9-]+):([a-z0-9\\.-]+):([a-z0-9-]+)?:([a-z0-9-]+)$",
                    "minLength": 0,
                    "maxLength": 146
                },
                "id": {
                    "type": "string",
                    "pattern": "^[A-Za-z0-9:_\\-]+$",
                    "minLength": 0,
                    "maxLength": 255
                },
                "tag": {
                    "type": "string",
                    "pattern": "^([\\w\\/-]|[\\w-][\\w\\/-]*[\\w-])$",
                    "minLength": 0,
                    "maxLength": 255
                }
            },
            "required": [
                "curie",
                "id"
            ],
            "additionalProperties": false,
            "description": "A fully qualified reference to what created this node. This is intentionally a message-ref and not a user id because it is often a program that creates nodes, not a user.",
            "pbj": {
                "type": "message-ref",
                "rule": "single"
            }
        },
        "updated_at": {
            "type": "string",
            "pattern": "^[1-9]{1}[0-9]{12,15}$",
            "pbj": {
                "type": "microtime",
                "rule": "single",
                "useTypeDefault": false
            }
        },
        "updater_ref": {
            "type": "object",
            "properties": {
                "curie": {
                    "type": "string",
                    "pattern": "^([a-z0-9-]+):([a-z0-9\\.-]+):([a-z0-9-]+)?:([a-z0-9-]+)$",
                    "minLength": 0,
                    "maxLength": 146
                },
                "id": {
                    "type": "string",
                    "pattern": "^[A-Za-z0-9:_\\-]+$",
                    "minLength": 0,
                    "maxLength": 255
                },
                "tag": {
                    "type": "string",
                    "pattern": "^([\\w\\/-]|[\\w-][\\w\\/-]*[\\w-])$",
                    "minLength": 0,
                    "maxLength": 255
                }
            },
            "required": [
                "curie",
                "id"
            ],
            "additionalProperties": false,
            "description": "A fully qualified reference to what updated this node. This is intentionally a message-ref and not a user id because it is often a program that updates nodes, not a user. E.g. \"acme:iam:node:app:cli-scheduler\" or \"acme:iam:node:user:60c71df0-fda8-11e5-bfb9-30342d363854\"",
            "pbj": {
                "type": "message-ref",
                "rule": "single"
            }
        },
        "last_event_ref": {
            "type": "object",
            "properties": {
                "curie": {
                    "type": "string",
                    "pattern": "^([a-z0-9-]+):([a-z0-9\\.-]+):([a-z0-9-]+)?:([a-z0-9-]+)$",
                    "minLength": 0,
                    "maxLength": 146
                },
                "id": {
                    "type": "string",
                    "pattern": "^[A-Za-z0-9:_\\-]+$",
                    "minLength": 0,
                    "maxLength": 255
                },
                "tag": {
                    "type": "string",
                    "pattern": "^([\\w\\/-]|[\\w-][\\w\\/-]*[\\w-])$",
                    "minLength": 0,
                    "maxLength": 255
                }
            },
            "required": [
                "curie",
                "id"
            ],
            "additionalProperties": false,
            "description": "A reference to the last event that changed the state of this node. E.g. \"acme:blog:event:article-published:60c71df0-fda8-11e5-bfb9-30342d363854\"",
            "pbj": {
                "type": "message-ref",
                "rule": "single"
            }
        },
        "title": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "pre_render_code": {
            "type": "string",
            "minLength": 0,
            "maxLength": 65535,
            "description": "A string containing HTML that is injected into the application before the widget renders.",
            "pbj": {
                "type": "text",
                "rule": "single"
            }
        },
        "post_render_code": {
            "type": "string",
            "minLength": 0,
            "maxLength": 65535,
            "description": "A string containing HTML that is injected into the application after the widget renders.",
            "pbj": {
                "type": "text",
                "rule": "single"
            }
        },
        "show_border": {
            "type": "boolean",
            "pbj": {
                "type": "boolean",
                "rule": "single"
            }
        },
        "show_header": {
            "type": "boolean",
            "default": true,
            "pbj": {
                "type": "boolean",
                "rule": "single"
            }
        },
        "header_text": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "partner_url": {
            "type": "string",
            "pattern": "^(https?:\\/\\/)?([\\da-z\\.-]+)\\.([a-z\\.]{2,6})([\\/\\w \\.-]*)*\\/?$",
            "pbj": {
                "type": "text",
                "rule": "single",
                "format": "url"
            }
        },
        "partner_text": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "view_all_url": {
            "type": "string",
            "pattern": "^(https?:\\/\\/)?([\\da-z\\.-]+)\\.([a-z\\.]{2,6})([\\/\\w \\.-]*)*\\/?$",
            "pbj": {
                "type": "text",
                "rule": "single",
                "format": "url"
            }
        },
        "view_all_text": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "layout": {
            "type": "string",
            "pattern": "^([\\w\\/-]|[\\w-][\\w\\/-]*[\\w-])$",
            "minLength": 0,
            "maxLength": 255,
            "pbj": {
                "type": "string",
                "rule": "single",
                "format": "slug"
            }
        }
    },
    "required": [
        "_id"
    ],
    "additionalProperties": true
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Form meta schema",
    "description": "Schema used for data type validation.",
    "type": "array",
    "minItems": 1,
    "_uniqueItems": true,
    "items": {
        "oneOf": [
            {
                "$ref": "#/types/string"
            },
            {
                "$ref": "#/types/boolean"
            },
            {
                "$ref": "#/types/integer"
            },
            {
                "$ref": "#/types/decimal"
            },
            {
                "$ref": "#/types/date"
            },
            {
                "$ref": "#/types/datetime"
            },
            {
                "$ref": "#/types/secret"
            },
            {
                "$ref": "#/types/file"
            },
            {
                "$ref": "#/types/dir"
            },
            {
                "$ref": "#/types/url"
            },
            {
                "$ref": "#/types/json"
            },
            {
                "$ref": "#/types/list_string"
            },
            {
                "$ref": "#/types/list_integer"
            },
            {
                "$ref": "#/types/list_decimal"
            },
            {
                "$ref": "#/types/list_file"
            },
            {
                "$ref": "#/types/list_dir"
            },
            {
                "$ref": "#/types/list_url"
            }
        ]
    },
    "types": {
        "string": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:(string|text):$"
                },
                "value": {
                    "type": "string"
                }
            }
        },
        "boolean": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:boolean:$"
                },
                "value": {
                    "type": "boolean"
                }
            }
        },
        "integer": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^(basic:integer|data(:[a-z0-9:]+)?):$"
                },
                "value": {
                    "type": "integer"
                }
            }
        },
        "decimal": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:decimal:$"
                },
                "value": {
                    "type": "number"
                }
            }
        },
        "date": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:date:$"
                },
                "value": {
                    "type": "string",
                    "pattern": "^(19|20)\\d\\d-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01])$"
                }
            }
        },
        "datetime": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:datetime:$"
                },
                "value": {
                    "type": "string",
                    "pattern": "^(19|20)\\d\\d-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01]) (?:(?:([01]?\\d|2[0-3]):)?([0-5]?\\d):)?([0-5]?\\d)$"
                }
            }
        },
        "secret": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:secret:$"
                },
