{
    "$ref": "#/definitions/canonicalData",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "comments": [
        " This is a JSON Schema for 'canonical-data.json' files.     ",
        "                                                            ",
        " It enforces just a general structure for all exercises,    ",
        " optimising for the ability to represent example-based tests",
        " of the form 'function (input) == output'. Future expansions",
        " may allow for other types of tests such as property-based. ",
        "                                                            ",
        " The only thing enforced regarding how test data should be  ",
        " structured is the error encoding, because it was agreed    ",
        " and it doesn't restrict flexibility in a significant way.  ",
        "                                                            ",
        " Standardized property names may help when automatically    ",
        " deriving JSON parsers in some languages, so we followed    ",
        " a few conventions from the 'Google JSON Style Guide'.      ",
        "                                                            ",
        " Additionally, this schema strictly enforces letters, in    ",
        " lowerCamelCase, for naming the 'property' being tested. We ",
        " expect this regularity will allow an easier automatic      ",
        " generation of function's names in test generators,         ",
        " slightly reducing the amount of manually generated code.   "
    ],
    "definitions": {
        "canonicalData": {
            "additionalProperties": false,
            "description": "This is the top-level file structure",
            "properties": {
                "cases": {
                    "$ref": "#/definitions/testGroup"
                },
                "comments": {
                    "$ref": "#/definitions/comments"
                },
                "exercise": {
                    "$ref": "#/definitions/exercise"
                },
                "version": {
                    "$ref": "#/definitions/version"
                }
            },
            "required": [
                "exercise",
                "version",
                "cases"
            ],
            "type": "object"
        },
        "comments": {
            "description": "An array of strings to fake multi-line comments",
            "items": {
                "type": "string"
            },
            "minItems": 1,
            "type": "array"
        },
        "description": {
            "description": "A short, clear, one-line description",
            "type": "string"
        },
        "error": {
            "description": "A message describing an error condition",
            "type": "string"
        },
        "exercise": {
            "description": "Exercise's slug (kebab-case)",
            "pattern": "^[a-z]+(-[a-z]+)*$",
            "type": "string"
        },
        "expected": {
            "dependencies": {
                "error": {
                    "maxProperties": 1
                }
            },
            "description": "The expected return value of a test case",
            "properties": {
                "error": {
                    "$ref": "#/definitions/error"
                }
            }
        },
        "input": {
            "description": "The inputs to a test case",
            "type": "object"
        },
        "labeledTest": {
            "additionalProperties": false,
            "description": "A single test with a description",
            "properties": {
                "comments": {
                    "$ref": "#/definitions/comments"
                },
                "description": {
                    "$ref": "#/definitions/description"
                },
                "expected": {
                    "$ref": "#/definitions/expected"
                },
                "input": {
                    "$ref": "#/definitions/input"
                },
                "optional": {
                    "$ref": "#/definitions/optional"
                },
                "property": {
                    "$ref": "#/definitions/property"
                }
            },
            "required": [
                "description",
                "property",
                "input",
                "expected"
            ],
            "type": "object"
        },
        "labeledTestGroup": {
            "additionalProperties": false,
            "description": "A group of tests with a description",
            "properties": {
                "cases": {
                    "$ref": "#/definitions/testGroup"
                },
                "comments": {
                    "$ref": "#/definitions/comments"
                },
                "description": {
                    "$ref": "#/definitions/description"
                },
                "optional": {
                    "$ref": "#/definitions/optional"
                }
            },
            "required": [
                "description",
                "cases"
            ],
            "type": "object"
        },
        "labeledTestItem": {
            "description": "A single test or group of tests with a description",
            "oneOf": [
                {
                    "$ref": "#/definitions/labeledTest"
                },
                {
                    "$ref": "#/definitions/labeledTestGroup"
                }
            ]
        },
        "optional": {
            "description": "An identifier for similar optional test cases (kebab-case)",
            "pattern": "^[a-z]+(-[a-z]+)*$",
            "type": "string"
        },
        "property": {
            "description": "A letters-only, lowerCamelCase property name",
            "pattern": "^[a-z]+([A-Z][a-z]+)*[A-Z]?$",
            "type": "string"
        },
        "testGroup": {
            "description": "An array of labeled test items",
            "items": {
                "$ref": "#/definitions/labeledTestItem"
            },
            "minItems": 1,
            "type": "array"
        },
        "version": {
            "description": "Semantic versioning: MAJOR.MINOR.PATCH",
            "pattern": "^(0|[1-9][0-9]*)(\\.(0|[1-9][0-9]*)){2}$",
            "type": "string"
        }
    },
    "self": {
        "format": "jsonschema",
        "name": "canonical-data",
        "vendor": "io.exercism",
        "version": "1-1-0"
    }
}

{
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "definitions": {
        "pushdataentry": {
            "type": "object",
            "title": "pushdataentry",
            "properties": {
                "url": {
                    "type": "string",
                    "description": "full URL of the middleware to push data to e.g. http://127.0.0.1/push/data.json"
                }
            },
            "required": [
                "url"
            ]
        },
        "local": {
            "type": "object",
            "properties": {
                "enabled": {
                    "type": "boolean",
                    "description": "should we start the local HTTPd for serving live readings?"
                },
                "port": {
                    "type": "integer",
                    "default": 8080,
                    "description": "the TCP port for the local HTTPd"
                },
                "index": {
                    "type": "boolean",
                    "description": "should we provide a index listing of available channels if no UUID was requested?"
                },
                "timeout": {
                    "type": "integer"
                },
                "buffer": {
                    "type": "integer"
                }
            },
            "required": [
                "enabled"
            ]
        },
        "channel": {
            "type": "object",
            "title": "channel",
            "properties": {
                "uuid": {
                    "type": "string",
                    "description": "uuid of this channel towards the middleware"
                },
                "identifier": {
                    "type": "string",
                    "description": "identifier of this channel from the meter. E.g. 1-0:1.8.0"
                },
                "api": {
                    "type": "string",
                    "enum": [
                        "volkszaehler",
                        "mysmartgrid",
                        "null"
                    ],
                    "default": "volkszaehler",
                    "description": "middleware api to be used. Defaults to volkszaehler.org"
                },
                "middleware": {
                    "type": "string",
                    "default": "http://localhost/middleware.php",
                    "description": "path/url to the api/middleware"
                },
                "secretKey": {
                    "type": "string",
                    "description": "secret key to use to talk to MySmartGrid api."
                },
                "type": {
                    "type": "string",
                    "enum": [
                        "device",
                        "sensor"
                    ],
                    "default": "device",
                    "description": "type of connected meter. Only needed for MySmartGrid api."
                },
                "scaler": {
                    "type": "integer",
                    "default": 1,
                    "description": "scaling factor to use. Only needed for MySmartGrid api."
                },
                "aggmode": {
                    "type": "string",
                    "enum": [
                        "avg",
                        "max",
                        "sum",
                        "none"
                    ],
                    "description": "Mittelwert fuer Leistung, MAX fuer Zaehler, SUM fuer Counter",
                    "default": "none"
                },
                "duplicates": {
                    "type": "integer",
                    "minimum": 0,
                    "default": 0,
                    "description": "default 0 (send duplicate values), >0 = send duplicate values only each <duplicates> seconds. Activate only for abs. counter values (Zaehlerstaende) and not for impulses!"
                }
            },
            "required": [
                "uuid",
                "identifier"
            ]
        },
        "meter": {
            "type": "object",
            "title": "meter",
            "properties": {
                "enabled": {
                    "type": "boolean",
                    "description": "enable or disable this meter. Disabled meter will be ignored.",
                    "default": false
                },
                "allowskip": {
                    "type": "boolean",
                    "description": "if enabled, errors when opening meter will lead to meter being ignored",
                    "default": false
                },
                "interval": {
                    "type": "integer",
                    "description": "delay in secs between queries to the meter",
                    "default": -1
                },
                "aggtime": {
                    "type": "integer",
                    "description": "aggregate all signals and give one update to middleware every <aggtime> seconds",
                    "default": -1
                },
                "aggfixedinterval": {
                    "type": "boolean",
                    "description": "round all timestamps to middleware to nearest aggtime",
                    "default": false
                },
                "channels": {
                    "$ref": "#/definitions/channels"
                }
            },
            "required": []
        },
        "meterInvalid": {
            "title": "invalid config for a meter. Choose any of the supported ones.",
            "allOf": [
                {
                    "$ref": "#/definitions/meter"
                },
                {
                    "properties": {
                        "protocol": {
                            "type": "string",
                            "enum": [
                                "invalid"
                            ]
                        }
                    }
                }
            ]
        },
        "meterS0": {
            "title": "S0 based meter",
            "allOf": [
                {
                    "$ref": "#/definitions/meter"
                },
                {
                    "properties": {
                        "protocol": {
                            "type": "string",
                            "enum": [
                                "s0"
                            ]
                        },
                        "device": {
                            "type": "string",
                            "description": "UART device the meter is connected to. E.g. /dev/ttyUSB0"
                        },
                        "gpio": {
                            "type": "integer",
                            "default": -1,
                            "description": "Number of GPIO port to be used. If this is set >-1 then device is ignored."
                        },
                        "mmap": {
                            "type": "string",
                            "default": "",
                            "description": "For gpio based devices and high frequency signals (>5-10kHz on a rpi2) memory mapped gpio can be used. Currently only supported on Raspberry-Pi 1 or 2. Leads to a constant but high CPU load depending on nonblocking_delay value. MMAPed GPIO pins need to be configured manually as input pins.",
                            "enum": [
                                "",
                                "rpi1",
                                "rpi2"
                            ]
                        },
                        "gpio_dir": {
                            "type": "integer",
                            "default": -1,
                            "description": "Number of GPIO port to be used as directional pin. If this pin is used and active Impulses_neg instead of Impulses is returned. Keep to -1 if unsure about the purpose."
                        },
                        "configureGPIO": {
                            "type": "boolean",
                            "default": true,
                            "description": "If true then vzlogger will export, configure,... the GPIO port. Needs proper access rights to /sys/class/gpio/."
                        },
                        "resolution": {
                            "type": "integer",
                            "default": 1000,
                            "description": "number of impulses per kWh"
                        },
                        "send_zero": {
                            "type": "boolean",
                            "default": false,
                            "description": "If active/true send data once a second even if no impulses have been received. Use aggregation is this case to reduce frequency."
                        },
                        "debounce_delay": {
                            "type": "integer",
                            "default": 30,
                            "description": "Delay in ms until the next edge is detected"
                        },
                        "nonblocking_delay": {
                            "type": "integer",
                            "default": 100000,
                            "description": "Delay in ns for polling/non-blocking interface. On an rpi2 e.g. 5000 can be used to detect up to 30kHz signals with mmap active."
                        }
                    },
                    "required": [
                        "protocol",
                        "device"
                    ]
                }
            ]
        },
        "meterD0": {
            "title": "D0 based meter",
            "allOf": [
                {
                    "$ref": "#/definitions/meter"
                },
                {
                    "properties": {
                        "protocol": {
                            "type": "string",
                            "enum": [
                                "d0"
