                },
                "display": {
                    "anyOf": [
                        {
                            "$ref": "#/definitions/display_type"
                        },
                        {
                            "type": "string",
                            "pattern": "^string_table\\:(([0-9A-Z]{8})-([0-9A-Z]{4})-([0-9A-Z]{4})-([0-9A-Z]{4})-([0-9A-Z]{12}))$"
