    "properties": {
        "id": {
            "type": "string",
            "description": "Every collection is identified by the unique value of this field. The value of this field is usually easiest to generate using a [UID](https://tools.ietf.org/html/rfc4122#section-4.4%29) generator function. If you already have a collection, it is recommended that you maintain the same id since changing the id usually implies that this is a different collection than it was originally."
        },
        "name": {
            "type": "string",
            "description": "A collection's friendly name is defined by this field. You would want to set this field to a value that would allow you to easily identify this collection among a bunch of other collections, as such outlining its usage or content."
        },
        "description": {
            "oneOf": [
                {
                    "type": "string"
                },
                {
                    "type": "null"
                }
            ],
            "description": "Provide a long description of this collection using this field. This field supports markdown syntax to better format the description."
        },
        "order": {
            "type": "array",
            "items": {
                "type": "string"
            },
            "_uniqueItems": true,
            "description": "The order array ensures that your requests and folders don't randomly get shuffled up. It holds a sequence of [UUIDs](https://en.wikipedia.org/wiki/Universally_unique_identifier) corresponding to folders and requests.\n *Note that if a folder ID or a request ID (if the request is not already part of a folder) is not included in the order array, the request or the folder will not show up in the collection.*"
        },
        "folders": {
            "type": "array",
            "items": {
                "title": "Folder",
                "description": "One of the primary goals of Postman is to organize the development of APIs. To this end, it is necessary to be able to group requests together. This can be achived using 'Folders'. A folder just is an ordered set of requests.",
                "type": "object",
                "properties": {
                    "id": {
                        "type": "string",
                        "description": "In order to be able to uniquely identify different folders within a collection, Postman assigns each folder a unique ID (a [UUID](https://en.wikipedia.org/wiki/Globally_unique_identifier)). This field contains that value."
                    },
                    "name": {
                        "type": "string",
                        "description": "A folder's friendly name is defined by this field. You would want to set this field to a value that would allow you to easily identify this folder."
                    },
                    "description": {
                        "type": "string",
                        "description": "Essays about the folder go into this field!"
                    },
                    "order": {
                        "type": "array",
                        "items": {
                            "type": "string"
                        },
                        "_uniqueItems": true,
                        "description": "Postman preserves the order of your requests within each folder. This field holds a sequence of [UUIDs](https://en.wikipedia.org/wiki/Globally_unique_identifier), where each ID corresponds to a particular Postman request."
                    },
                    "collection": {
                        "type": "string",
                        "description": "Postman folders are always a part of a collection. That collection's unique ID (which is a [UUID](https://en.wikipedia.org/wiki/Globally_unique_identifier)) is stored in this field."
                    }
                },
                "required": [
                    "id",
                    "owner",
                    "collection",
                    "name",
                    "description",
                    "order"
                ]
            },
            "description": "Folders are the way to go if you want to group your requests and to keep things organised. Folders can also be useful in sequentially requesting a part of the entire collection by using [Postman Collection Runner](https://www.getpostman.com/docs/jetpacks_running_collections) or [Newman](https://github.com/postmanlabs/newman) on a particular folder."
        },
        "timestamp": {
            "type": "number",
            "multipleOf": 1
        },
        "requests": {
            "type": "array",
            "description": "",
            "items": {
                "title": "Request",
                "description": "A request represents an HTTP request.",
                "type": "object",
                "properties": {
                    "folder": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "Postman requests may or may not be a part of a folder. If this request belongs to a folder, that folder's unique ID (which is a [UUID](https://en.wikipedia.org/wiki/Globally_unique_identifier)) is stored in this field."
                    },
                    "id": {
                        "type": "string",
                        "description": "Postman can store a number of requests in each collection. In order to preserve the order of each request, we need to be able to identify requests uniquely. This field is a UUID assigned to each request."
                    },
                    "name": {
                        "type": "string",
                        "description": "Sometimes, you just need to call your request 'Bob'. Postman will let you do that, and store the name you give in this field."
                    },
                    "dataMode": {
                        "type": "string",
                        "enum": [
                            "raw",
                            "urlencoded",
                            "params"
                        ],
                        "description": "A request can have a specific data mode, and Postman supports three."
                    },
                    "data": {
                        "type": "array",
                        "description": "Data is an array of key-values that the request goes with. POST data, PUT data, etc goes here.",
                        "items": {
                            "type": "object",
                            "properties": {
                                "key": {
                                    "type": "string"
                                },
                                "value": {
                                    "type": "string"
                                },
                                "enabled": {
                                    "type": "boolean"
                                },
                                "type": {
                                    "enum": [
                                        "file",
                                        "text"
                                    ]
                                }
                            }
                        }
                    },
                    "descriptionFormat": {
                        "oneOf": [
                            {
                                "type": "string",
                                "enum": [
                                    "html",
                                    "markdown"
                                ]
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "A request can have an associated description text. Since description is meant to be long, it can be in either ``html`` or ``markdown`` formats. This field specifies that format."
                    },
                    "description": {
                        "type": "string",
                        "description": "The description of this request. Can be as long as you want. Postman also supports two formats for your description, ``markdown`` and ``html``."
                    },
                    "headers": {
                        "type": "string",
                        "description": "No HTTP request is complete without its headers, and the same is true for a Postman request. This field contains all the HTTP Headers in a raw string format."
                    },
                    "method": {
                        "type": "string",
                        "enum": [
                            "GET",
                            "PUT",
                            "POST",
                            "PATCH",
                            "DELETE",
                            "COPY",
                            "HEAD",
                            "OPTIONS",
                            "LINK",
                            "UNLINK",
                            "PURGE",
                            "LOCK",
                            "UNLOCK",
                            "PROPFIND",
                            "VIEW"
                        ],
                        "description": "The HTTP method associated with this request."
                    },
                    "pathVariables": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "object"
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "A Postman request allows you to use Path Variabled in a request, e.g: ``{{url}}``. This field stores these variables."
                    },
                    "url": {
                        "type": "string",
                        "description": "Contains the complete URL for this request, along with the path variables, if any."
                    },
                    "preRequestScript": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "In some use cases, it's necessary to run a bit of code or perform some tasks before sending a request. Postman implements this feature by the use of this field. Any code written to this field is run before running a request."
                    },
                    "tests": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "Postman allows you to define a script that is run after executing the request, which may act on the response. Such a script is stored in this field."
                    },
                    "time": {
                        "type": "number",
                        "multipleOf": 1,
                        "description": "The timestamp for this request."
                    },
                    "responses": {
                        "type": "array",
                        "description": "A Postman request can have multiple responses associated with it. These responses are stored in this field.",
                        "items": {
                            "title": "Response",
                            "description": "A response represents an HTTP response.",
                            "properties": {
                                "request": {
                                    "oneOf": [
                                        {
                                            "type": "string"
                                        },
                                        {
                                            "type": "object"
                                        }
                                    ],
                                    "description": "A response is associated with a request. This fields contains the UUID of the request corresponding to this response."
                                },
                                "id": {
                                    "type": "string",
                                    "description": "In order to unambiguously identify a response, Postman assigns a UUID to it, and stores it in this field."
                                },
                                "name": {
                                    "type": "string",
                                    "description": "A response can have a friendly name, which goes here."
                                },
                                "status": {
                                    "type": "string",
                                    "description": ""
                                },
                                "responseCode": {
                                    "type": "object",
                                    "properties": {
                                        "code": {
                                            "type": "number",
                                            "description": "The numeric HTTP response code."
                                        },
                                        "name": {
                                            "type": "string",
                                            "description": "The textual HTTP response code."
                                        },
                                        "detail": {
                                            "type": "string",
                                            "description": "Detailed explanation of the response code."
                                        }
                                    },
                                    "required": [
                                        "code",
                                        "name"
                                    ]
                                },
                                "time": {
                                    "oneOf": [
                                        {
                                            "type": "string"
                                        },
                                        {
                                            "type": "number"
                                        }
                                    ],
                                    "description": "The time taken by this particular HTTP transaction to complete is stored in this field."
                                },
                                "headers": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "name": {
                                                "type": "string",
                                                "description": "Some headers can have names associated with them, which are stored in this field."
                                            },
                                            "key": {
                                                "type": "string",
                                                "description": "The left hand side (LHS) or 'key' of the header."
                                            },
                                            "value": {
                                                "type": "string",
                                                "description": "Value of the header, or the right hand side (RHS)."
                                            },
                                            "description": {
                                                "type": "string",
                                                "description": "An optional description about the header."
                                            }
                                        },
                                        "required": [
                                            "name",
                                            "key",
                                            "value"
                                        ]
                                    }
                                },
                                "cookies": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "domain": {
                                                "type": "string",
                                                "description": "The domain for which this cookie is valid."
                                            },
                                            "expirationDate": {
                                                "type": "number",
                                                "description": "The timestamp of the time when the cookie expires."
                                            },
                                            "hostOnly": {
                                                "type": "boolean",
                                                "description": "Indicates if this cookie is Host Only."
                                            },
                                            "httpOnly": {
                                                "type": "boolean",
                                                "description": "Indicates if this cookie is HTTP Only."
                                            },
                                            "name": {
                                                "type": "string",
                                                "description": "This is the name of the Cookie."
                                            },
                                            "path": {
                                                "type": "string",
                                                "description": "The path associated with the Cookie."
                                            },
                                            "secure": {
                                                "type": "boolean",
                                                "description": "Indicates if the 'secure' flag is set on the Cookie."
                                            },
                                            "session": {
                                                "type": "boolean",
                                                "description": "True if the cookie is a session cookie."
                                            },
                                            "storeId": {
                                                "type": "string",
                                                "description": "The ID of the cookie store containing this cookie."
                                            },
                                            "value": {
                                                "type": "string",
                                                "description": "The value of the Cookie."
                                            },
                                            "expires": {
                                                "type": "string",
                                                "description": "Human readable expiration time."
                                            }
                                        },
                                        "required": [
                                            "domain",
                                            "expirationDate",
                                            "hostOnly",
                                            "httpOnly",
                                            "name",
                                            "path",
                                            "secure",
                                            "session",
                                            "storeId",
                                            "value",
                                            "expires"
                                        ]
                                    }
                                },
                                "mime": {
                                    "type": "string",
                                    "description": "Mimetype of the response."
                                },
                                "text": {
                                    "type": "string",
                                    "description": "The raw text of the response."
                                },
                                "language": {
                                    "type": "string",
                                    "enum": [
                                        "html",
                                        "javascript",
                                        "xml"
                                    ],
                                    "description": "The language associated with the response."
                                },
                                "rawDataType": {
                                    "type": "string",
                                    "description": "The data type of the raw response."
                                }
                            },
                            "required": [
                                "id",
                                "responseCode",
                                "request"
                            ]
                        }
                    },
                    "rawModeData": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "null"
                            },
                            {
                                "type": "array"
                            }
                        ],
                        "description": "Contains the raw data (parameters) that Postman sends to the server"
                    }
                },
                "required": [
                    "id",
                    "method",
                    "url",
                    "headers",
                    "name"
                ]
            }
        }
    },
    "required": [
        "id",
        "name",
        "order",
        "requests"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Assessment info",
    "description": "Configuration data for an assessment.",
    "type": "object",
    "additionalProperties": false,
    "required": [
        "uuid",
        "type",
        "title",
        "set",
        "number"
    ],
    "properties": {
        "uuid": {
            "description": "Unique identifier (UUID v4).",
            "type": "string",
            "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
        },
        "type": {
            "description": "Type of the assessment.",
            "enum": [
                "Homework",
                "Exam"
            ]
        },
        "title": {
            "description": "The title of the assessment (e.g., 'Derivatives and anti-derivatives').",
            "type": "string"
        },
        "set": {
            "description": "Which assessmentSet this one belongs to (e.g., 'Homework', 'Practice Quiz').",
            "type": "string"
        },
        "number": {
            "description": "The number of this assessment within the set (e.g., '1', '2R', '3B').",
            "type": "string"
        },
        "allowIssueReporting": {
            "description": "Whether to allow students to report issues for assessment questions",
            "type": "boolean",
            "default": true
        },
        "multipleInstance": {
            "description": "Whether to allow students to create additional instances of the assessment",
            "type": "boolean",
            "default": false
        },
        "shuffleQuestions": {
            "description": "Whether the questions will be shuffled in the student view of an assessment (Homework only)",
            "type": "boolean",
            "default": false
        },
        "allowAccess": {
            "description": "List of access rules for the assessment. Access is permitted if any access rule is satisfied.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/accessRule"
            }
        },
        "text": {
            "description": "HTML text shown on the assessment overview page.",
            "type": "string"
        },
        "maxPoints": {
            "description": "The maximum number of points that can be earned for this assessment.",
            "type": "number"
        },
        "autoClose": {
            "description": "Whether to automatically close the assessment after a period of inactivity.",
            "type": "boolean",
            "default": true
        },
        "zones": {
            "description": "Array of \"zones\" in the assessment, each containing questions that can be randomized within the zone.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/zone"
            }
        },
        "constantQuestionValue": {
            "description": "Whether to keep the value of a question constant after a student solves it correctly.",
            "type": "boolean",
            "default": false
        },
        "allowRealTimeGrading": {
            "description": "Removes the student \"Grade\" buttons to prevent real-time grading while the assessment is being taken.",
            "type": "boolean",
            "default": true
        },
        "requireHonorCode": {
            "description": "Requires the student to accept an honor code before starting exam assessments.",
            "type": "boolean",
            "default": true
        }
    },
    "definitions": {
        "accessRule": {
            "description": "An access rule that permits people to access this assessment. All restrictions in the rule must be satisfied for the rule to allow access.",
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "mode": {
                    "description": "The server mode required for access.",
                    "enum": [
                        "Public",
                        "Exam",
                        "SEB"
                    ]
                },
                "examUuid": {
                    "description": "The scheduler exam UUID for which a student must be registered.",
                    "type": "string",
                    "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
                },
                "role": {
                    "description": "The minimum user role required for access.",
                    "enum": [
                        "Student",
                        "TA",
                        "Instructor"
                    ]
                },
                "uids": {
                    "description": "A list of UIDs (like 'username@example.com', one of which is required for access",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "credit": {
                    "description": "How much credit is awarded for doing the homework, as a percentage (100 means full credit).",
                    "type": "integer",
                    "minimum": 0
                },
                "startDate": {
                    "description": "The earliest date on which access is permitted.",
                    "type": "string"
                },
                "endDate": {
                    "description": "The latest date on which access is permitted.",
                    "type": "string"
                },
                "timeLimitMin": {
                    "description": "The time limit to complete the assessment, in minutes (only for Exams).",
                    "type": "integer",
                    "minimum": 0
                },
                "password": {
                    "description": "Password to begin the assessment (only for Exams).",
                    "type": "string"
                },
                "SEBConfig": {
                    "description": "Configuration related to Safe Exam Browser",
                    "type": "object",
                    "properties": {
                        "password": {
                            "description": "Password protect the SEB exam and config file",
                            "type": "string"
                        },
                        "quitPassword": {
                            "description": "If set, requires password to quit SEB other than visiting the quitURL page",
                            "type": "string"
                        },
                        "allowPrograms": {
                            "description": "Keyword array for allowed programs in SEB",
                            "type": "array",
                            "minItems": 0,
                            "items": {
                                "type": "string"
                            }
                        }
                    }
                },
                "showClosedAssessment": {
                    "description": "Whether the student can view the assessment after it has been closed",
                    "type": "boolean",
                    "default": true
                }
            }
        },
        "zone": {
            "type": "object",
            "properties": {
                "title": {
                    "description": "Zone title, displayed to the students at the top of the question list for the zone.",
                    "type": "string"
                },
                "maxPoints": {
                    "description": "Only this many of the points that are awarded for answering questions in this zone will count toward the total points.",
                    "type": "number"
                },
                "numberChoose": {
                    "description": "Number of questions to choose from this zone.",
                    "type": "integer",
                    "minimum": 0
                },
                "bestQuestions": {
                    "description": "Only this many of the questions in this zone, with the highest number of awarded points, will count toward the total points.",
                    "type": "integer",
                    "minimum": 0
                },
                "questions": {
                    "description": "Array of questions in the zone.",
                    "type": "array",
                    "minItems": 1,
                    "items": {
                        "$ref": "#/definitions/zoneQuestion"
                    }
                }
            },
            "required": [
                "questions"
            ]
        },
        "zoneQuestion": {
            "type": "object",
            "properties": {
                "points": {
                    "$ref": "#/definitions/points"
                },
                "maxPoints": {
                    "$ref": "#/definitions/pointsSingle"
                },
                "id": {
                    "$ref": "#/definitions/questionId"
                },
                "forceMaxPoints": {
                    "$ref": "#/definitions/forceMaxPoints"
                },
                "alternatives": {
                    "description": "Array of question alternatives to choose from.",
                    "type": "array",
                    "minItems": 1,
                    "items": {
                        "$ref": "#/definitions/questionAlternative"
                    }
                },
                "numberChoose": {
                    "description": "Number of questions to choose from this group.",
                    "type": "integer",
                    "minimum": 0,
                    "default": 1
                },
                "triesPerVariant": {
                    "description": "The maximum number of graded submissions allowed for each question instance.",
                    "type": "number",
                    "default": 1
                }
            }
        },
        "questionAlternative": {
            "type": "object",
            "properties": {
                "points": {
                    "$ref": "#/definitions/points"
                },
                "maxPoints": {
                    "$ref": "#/definitions/pointsSingle"
                },
                "id": {
                    "$ref": "#/definitions/questionId"
                },
                "forceMaxPoints": {
                    "$ref": "#/definitions/forceMaxPoints"
                },
                "triesPerVariant": {
                    "description": "The maximum number of graded submissions allowed for each question instance.",
                    "type": "number",
                    "default": 1
                }
            }
        },
        "points": {
            "oneOf": [
                {
                    "$ref": "#/definitions/pointsSingle"
                },
                {
                    "$ref": "#/definitions/pointsList"
                }
            ]
        },
        "pointsSingle": {
            "description": "A single point value.",
            "type": "number",
            "minimum": 0,
            "default": 1
        },
        "pointsList": {
            "description": "An array of point values.",
            "type": "array",
            "minItems": 1,
            "items": {
                "$ref": "#/definitions/points"
            }
        },
        "questionId": {
            "description": "Question ID (directory name of the question).",
            "type": "string"
        },
        "forceMaxPoints": {
            "description": "Whether to force this question to be awarded maximum points on a regrade.",
            "type": "boolean",
            "default": false
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "additionalProperties": false,
    "definitions": {
        "absolute_path": {
            "description": "A path only. Query string and/or fragment are not allowed.",
            "pattern": "^/(([a-zA-Z0-9._~!$&'()*+,;=:@-]|%[0-9a-fA-F]{2})+(/([a-zA-Z0-9._~!$&'()*+,;=:@-]|%[0-9a-fA-F]{2})*)*)?$",
            "type": "string"
        },
        "analytics_identifier": {
            "anyOf": [
                {
                    "type": "string"
                },
                {
                    "type": "null"
                }
            ],
            "description": "A short identifier we send to Google Analytics for multi-valued fields. This means we avoid the truncated values we would get if we sent the path or slug of eg organisations."
        },
        "change_history": {
            "items": {
                "additionalProperties": false,
                "properties": {
                    "note": {
                        "description": "A summary of the change",
                        "type": "string"
                    },
                    "public_timestamp": {
                        "_format": "date-time",
                        "type": "string"
                    }
                },
                "required": [
                    "public_timestamp",
                    "note"
                ],
                "type": "object"
            },
            "type": "array"
        },
        "description": {
            "type": "string"
        },
        "description_optional": {
            "anyOf": [
                {
                    "$ref": "#/definitions/description"
                },
                {
                    "type": "null"
                }
            ]
        },
        "details": {
            "additionalProperties": false,
            "properties": {
                "breadcrumbs": {
                    "$ref": "#/definitions/email_alert_signup_breadcrumbs"
                },
                "change_history": {
                    "$ref": "#/definitions/change_history"
                },
                "email_alert_type": {
                    "enum": [
                        "topics",
                        "policies",
                        "countries"
                    ],
                    "type": "string"
                },
                "govdelivery_title": {
                    "type": "string"
                },
                "subscriber_list": {
                    "description": "The attributes used to match subscriber lists in email-alert-api",
                    "minProperties": 1,
                    "properties": {
                        "document_type": {
                            "description": "The document_type used to match subscribers lists",
                            "type": "string"
                        },
                        "links": {
